static DWORD rva_to_offset(const u8*base,size_t size,DWORD rva,const IMAGE_NT_HEADERS64*nt){(void)base;(void)size;auto sec=IMAGE_FIRST_SECTION(nt);for(unsigned i=0;i<nt->FileHeader.NumberOfSections;i++,sec++){DWORD span=(std::max)(sec->Misc.VirtualSize,sec->SizeOfRawData);if(rva>=sec->VirtualAddress&&rva<sec->VirtualAddress+span)return sec->PointerToRawData+(rva-sec->VirtualAddress);}return 0;}
static bool pe_audit_self(){Buffer b;if(file_read_path(self_path(),&b)!=Status::Ok||b.size()<sizeof(IMAGE_DOS_HEADER))return false;auto dos=(IMAGE_DOS_HEADER*)b.data();if(dos->e_magic!=IMAGE_DOS_SIGNATURE)return false;if((size_t)dos->e_lfanew+sizeof(IMAGE_NT_HEADERS64)>b.size())return false;auto nt=(IMAGE_NT_HEADERS64*)(b.data()+dos->e_lfanew);if(nt->Signature!=IMAGE_NT_SIGNATURE||nt->FileHeader.Machine!=IMAGE_FILE_MACHINE_AMD64)return false;WORD dc=nt->OptionalHeader.DllCharacteristics;WORD need=IMAGE_DLLCHARACTERISTICS_NX_COMPAT|IMAGE_DLLCHARACTERISTICS_DYNAMIC_BASE|IMAGE_DLLCHARACTERISTICS_HIGH_ENTROPY_VA|IMAGE_DLLCHARACTERISTICS_GUARD_CF;if((dc&need)!=need)return false;auto sec=IMAGE_FIRST_SECTION(nt);for(unsigned i=0;i<nt->FileHeader.NumberOfSections;i++,sec++)if((sec->Characteristics&IMAGE_SCN_MEM_EXECUTE)&&(sec->Characteristics&IMAGE_SCN_MEM_WRITE))return false;auto dir=nt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_IMPORT];if(dir.VirtualAddress){DWORD off=rva_to_offset(b.data(),b.size(),dir.VirtualAddress,nt);if(!off||off>=b.size())return false;auto imp=(IMAGE_IMPORT_DESCRIPTOR*)(b.data()+off);for(;imp->Name;imp++){DWORD no=rva_to_offset(b.data(),b.size(),imp->Name,nt);if(!no||no>=b.size())return false;std::string n=(char*)b.data()+no;for(auto&ch:n)ch=(char)std::tolower((unsigned char)ch);for(auto bad:{"python","node","coreclr","hostfxr","sqlite"})if(n.find(bad)!=std::string::npos)return false;}}return true;}
