static const char* domain_name(CourtDomain d){switch(d){case CourtDomain::FORMAT:return "FORMAT";case CourtDomain::JOURNAL:return "JOURNAL";case CourtDomain::OBJECT:return "OBJECT";case CourtDomain::PATH:return "PATH";case CourtDomain::FILE_IO:return "FILE";case CourtDomain::WRITE:return "WRITE";case CourtDomain::SECURITY:return "SECURITY";default:return "RUNTIME";}}
Status verify_court_registry(Digest256*out){if(std::size(REG)!=GENESIS_COURT_COUNT)return Status::TestFailed;std::string s="FUSE-GENESIS-SELF-COURT-REGISTRY-V1\n";for(auto&t:REG){if(!t.critical||!t.run)return Status::TestFailed;s+=t.id;s+='\t';s+=domain_name(t.domain);s+="\tCRITICAL\n";}auto st=sha256({(const u8*)s.data(),(u64)s.size()},out);return st==Status::Ok&&digest_hex(*out)==GENESIS_COURT_REGISTRY_SHA256?Status::Ok:Status::TestFailed;}
int run_self_court(CourtContext*c){Digest256 reg{};if(verify_court_registry(&reg)!=Status::Ok)return 101;u32 pass=0,run=0;for(auto&t:REG){CourtResult r=t.run(c);run++;printf("%s %s %s\n",r.verdict==CourtVerdict::PASS?"PASS":"FAIL",t.id,status_name(r.status));if(r.verdict==CourtVerdict::PASS)pass++;}printf("GENESIS_COURT discovered=%zu executed=%u passed=%u failed=%u registry=%s\n",std::size(REG),run,pass,run-pass,digest_hex(reg).c_str());return run==48&&pass==48?0:104;}
int run_court_child(const std::string&id,const std::wstring&root){if(id=="MVS-CRASH")return run_mvs_crash_child(root);if(id=="JRN-002"||id=="JRN-003"||id=="JRN-004"){JournalWriter w{};journal_writer_open(root,&w);append_simple(&w,1);auto p=(std::filesystem::path(root)/L"segment-0000000000000001.fsj").wstring();FcbWriter fw{};fcb_begin(&fw,1,0);fcb_put_u64(&fw,1,2);Buffer payload;fcb_finish(&fw,&payload,nullptr);JournalRecordInput in{};in.sequence=2;in.previous_record_hash=w.previous_hash;in.payload={payload.data(),(u64)payload.size()};Buffer rec;fsj_build(&in,&rec,nullptr);size_t cut=id=="JRN-002"?50:(id=="JRN-003"?150:rec.size()-10);HANDLE h=CreateFileW(p.c_str(),FILE_APPEND_DATA,0,nullptr,OPEN_EXISTING,FILE_FLAG_WRITE_THROUGH,nullptr);DWORD n=0;WriteFile(h,rec.data(),(DWORD)cut,&n,nullptr);FlushFileBuffers(h);CloseHandle(h);TerminateProcess(GetCurrentProcess(),0x47A5);}return 2;}
